entries[74246] = { ["name"] = "Entschlüsselungsring des Kryptomanten", ["text"] = "Questgegenstand\nEinzigartig\n\"Aus dem Auge der Ewigkeit entwendet, jedoch offenbar inaktiv.\"" }
