entries[74269] = { ["name"] = "Flammender Hippogryph", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 20\nBenötigt Unerfahrener Reiter\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren flammenden Hippogryph oder gibt ihn wieder frei. Das ist ein Flugreittier." }
entries[74274] = { ["name"] = "Pläne: Phantomklinge", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (270)\nBenutzen: Lehrt Euch das Schmieden einer Phantomklinge.\n\nPhantomklinge\nWird beim Anlegen gebunden\nEinhändig Schwert\n59 - 111 Schaden Tempo 2.60\n(32.69 Schaden pro Sekunde)\nHaltbarkeit 90 / 90\nBenötigt Stufe 44\nTrefferchance: Verringert die Rüstung des Ziels 20 Sek. lang um 100. Während der Wirkungsdauer kann das Ziel weder Verstohlenheit anwenden noch unsichtbar werden.\nVerkaufspreis:\nBenötigt Mithrilbarren (28), Odem des Windes (6), Echtsilberbarren (8), Geringer Unsichtbarkeitstrank (2), Aquamarin (6), Robuster Schleifstein (4), Dickes Leder (2)" }
entries[74278] = { ["name"] = "Helm des Sonnenwendfests", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKopf\n43 Rüstung\nBenutzen: Kniet nieder, damit andere auf Euch kochen können. (10 Sek. Abklingzeit)" }
